-- Djecka's survivor (tools/blender/survivor_model.py) as the other player's body. No cooked asset: one ProceduralMeshComponent per
-- bone (geometry in survivor_mesh.lua, generated by tools/blender/survivor_mesh_data.py), attached to the remote character's
-- CharacterMesh0 at that bone, so the game's replicated ALS animation drives it. The mannequin itself stays invisible.
-- Part placement: REF is the mannequin's reference pose (component space, cm, rotation as quaternion) read live from an
-- unanimated copy of its mesh. Each part is rotated about its bone origin from the survivor's rest bone direction onto the
-- mannequin's (so arms follow its A-pose), then into the bone's local frame. Never on our own body (session.lua decides).
local common = require("common")
local log = common.log

local M = {}
function M.enabled() return os.getenv("PT_MUTATE") ~= "nosurvivor" end

local REF = {
    pelvis={0.00,-1.06,96.75,0.00129,0.70711,-0.00129,-0.70711},
    spine_01={0.00,-0.17,107.56,-0.04540,-0.70565,0.04540,0.70565},
    spine_02={0.00,-1.52,126.76,-0.04133,0.70590,0.04133,-0.70590},
    spine_03={0.00,-3.50,140.03,0.05844,-0.70469,-0.05844,0.70469},
    neck_01={0.00,-5.88,156.42,0.08634,0.70182,-0.08634,-0.70182},
    head={0.00,-3.98,165.52,0.00815,-0.70706,-0.00815,0.70706},
    clavicle_l={3.78,-2.76,152.20,-0.01949,-0.08265,0.22868,-0.96979},
    upperarm_l={17.70,-9.71,149.53,-0.00264,0.41962,-0.03874,0.90687},
    lowerarm_l={37.26,-11.91,126.45,-0.15391,-0.32959,-0.17923,-0.91409},
    hand_l={56.65,-0.34,111.68,0.67879,0.38914,-0.06954,0.61885},
    middle_01_l={64.49,4.48,103.48,-0.56504,-0.48211,0.21835,-0.63295},
    thigh_l={9.01,-0.53,95.30,-0.05834,-0.74127,-0.04581,0.66710},
    calf_l={13.40,-1.61,52.97,0.07609,0.73787,-0.03618,-0.66966},
    foot_l={17.08,-8.07,13.47,-0.02053,-0.71223,-0.01172,0.70155},
    ball_l={17.91,8.36,2.81,0.52617,0.48050,-0.49594,-0.49629},
    clavicle_r={-3.78,-2.76,152.20,0.96979,0.22868,0.08265,-0.01949},
    upperarm_r={-17.70,-9.71,149.53,-0.90687,-0.03874,-0.41962,-0.00264},
    lowerarm_r={-37.26,-11.91,126.45,0.91409,-0.17923,0.32959,-0.15391},
    hand_r={-56.65,-0.34,111.68,-0.61885,-0.06954,-0.38914,0.67879},
    middle_01_r={-64.49,4.48,103.48,0.63295,0.21835,0.48211,-0.56504},
    thigh_r={-9.01,-0.53,95.30,0.66710,0.04580,-0.74127,0.05834},
    calf_r={-13.40,-1.61,52.97,-0.66966,0.03618,0.73787,-0.07609},
    foot_r={-17.08,-8.07,13.47,0.70155,0.01172,-0.71223,0.02053},
    ball_r={-17.91,8.36,2.81,-0.49629,0.49594,0.48050,-0.52617},
}
-- the bone whose position gives the mannequin's bone direction (ball and head turn like the foot and the neck's tip)
local CHILD = { pelvis = "spine_01", spine_01 = "spine_02", spine_02 = "spine_03", spine_03 = "neck_01", neck_01 = "head",
    clavicle = "upperarm", upperarm = "lowerarm", lowerarm = "hand", hand = "middle_01", thigh = "calf", calf = "foot", foot = "ball" }
local SITTING = { thigh_l = true, thigh_r = true, calf_l = true, calf_r = true, foot_l = true, foot_r = true, ball_l = true, ball_r = true }
local FOOT_DOWN = { foot_l = true, foot_r = true, ball_l = true, ball_r = true } -- the mannequin's ankle is 4.5 cm above the survivor's

local function valid(o) return type(o) == "userdata" and o:IsValid() and not o:HasAnyInternalFlags(EInternalObjectFlags.PendingKill) end
local function sub(a, b) return { a[1] - b[1], a[2] - b[2], a[3] - b[3] } end
local function unit(a) local l = math.sqrt(a[1] ^ 2 + a[2] ^ 2 + a[3] ^ 2); return { a[1] / l, a[2] / l, a[3] / l } end
local function pos(n) local r = REF[n]; return { r[1], r[2], r[3] } end
local function rotOf(q) -- quaternion x y z w -> rows of the 3x3 matrix (local -> component)
    local x, y, z, w = q[1], q[2], q[3], q[4]
    return { { 1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w) },
             { 2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w) },
             { 2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y) } }
end
local function apply(m, v) return { m[1][1] * v[1] + m[1][2] * v[2] + m[1][3] * v[3], m[2][1] * v[1] + m[2][2] * v[2] + m[2][3] * v[3], m[3][1] * v[1] + m[3][2] * v[2] + m[3][3] * v[3] } end
local function applyT(m, v) return { m[1][1] * v[1] + m[2][1] * v[2] + m[3][1] * v[3], m[1][2] * v[1] + m[2][2] * v[2] + m[3][2] * v[3], m[1][3] * v[1] + m[2][3] * v[2] + m[3][3] * v[3] } end
local function between(a, b) -- shortest rotation taking unit a onto unit b (Rodrigues)
    local k = { a[2] * b[3] - a[3] * b[2], a[3] * b[1] - a[1] * b[3], a[1] * b[2] - a[2] * b[1] }
    local c = a[1] * b[1] + a[2] * b[2] + a[3] * b[3]
    local K = { { 0, -k[3], k[2] }, { k[3], 0, -k[1] }, { -k[2], k[1], 0 } }
    local r, f = {}, 1 / (1 + c)
    for i = 1, 3 do
        r[i] = {}
        for j = 1, 3 do
            local k2 = K[i][1] * K[1][j] + K[i][2] * K[2][j] + K[i][3] * K[3][j]
            r[i][j] = (i == j and 1 or 0) + K[i][j] + k2 * f
        end
    end
    return r
end

-- per bone: the section arrays as the game wants them (bone-local cm), built once per process
local built
local function build()
    local data = require("survivor_mesh")
    built = { colors = data.colors }
    for bone, b in pairs(data.bones) do
        local sfx = bone:match("_[lr]$") or ""
        local base = bone:sub(1, #bone - #sfx)
        local dmv
        if base == "head" then dmv = sub(pos("head"), pos("neck_01"))
        elseif base == "ball" then dmv = sub(pos(bone), pos("foot" .. sfx))
        else dmv = sub(pos(CHILD[base] .. sfx), pos(bone)) end
        local dm = unit(dmv)
        local ds = (base == "ball" and data.bones["foot" .. sfx] or b).dir
        local rmin = between(ds, dm)
        -- stretch along the bone to the mannequin's bone length (its spine is longer: bands of torso would show gaps)
        local dl = base == "head" and 22 or math.sqrt((dmv[1]) ^ 2 + dmv[2] ^ 2 + dmv[3] ^ 2)
        local k = math.max(0.8, math.min(1.7, dl / (base == "ball" and data.bones["foot" .. sfx].len or b.len)))
        if base == "ball" or base == "head" or base == "hand" then k = 1 end
        local rref = rotOf({ table.unpack(REF[bone], 4, 7) })
        local dz = FOOT_DOWN[bone] and -4.5 or 0
        local secs = {}
        for _, s in ipairs(b.sections) do
            local V, N = {}, {}
            for i = 1, #s.v, 3 do
                local v = { s.v[i], s.v[i + 1], s.v[i + 2] }
                local along = (k - 1) * (v[1] * ds[1] + v[2] * ds[2] + v[3] * ds[3])
                local p = apply(rmin, { v[1] + along * ds[1], v[2] + along * ds[2], v[3] + along * ds[3] })
                p = applyT(rref, { p[1], p[2], p[3] + dz })
                local n = applyT(rref, apply(rmin, { s.n[i], s.n[i + 1], s.n[i + 2] }))
                V[#V + 1] = { X = p[1], Y = p[2], Z = p[3] }
                N[#N + 1] = { X = n[1], Y = n[2], Z = n[3] }
            end
            secs[#secs + 1] = { mat = s.mat, v = V, n = N, t = s.t }
        end
        built[bone] = secs
    end
end

local BASE_MATERIALS = { "/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial", "/Engine/EngineMaterials/WorldGridMaterial.WorldGridMaterial" }
local function baseMaterial()
    for _, p in ipairs(BASE_MATERIALS) do
        local m = StaticFindObject(p)
        if not valid(m) then m = LoadAsset(p) end
        if valid(m) then return m end
    end
end

local bodies = {} -- character full name -> { char = ..., comps = { bone = component } }
local ID = { Rotation = { X = 0, Y = 0, Z = 0, W = 1 }, Translation = { X = 0, Y = 0, Z = 0 }, Scale3D = { X = 1, Y = 1, Z = 1 } }

local function attach(char, bone, secs, base)
    local cls = StaticFindObject("/Script/ProceduralMeshComponent.ProceduralMeshComponent")
    local comp = char:AddComponentByClass(cls, false, ID, false)
    if not valid(comp) then return nil end
    comp:K2_AttachToComponent(char.Mesh, FName(bone), 2, 2, 2, false)
    comp:SetCollisionEnabled(0)
    comp:SetCastShadow(false)
    for i, s in ipairs(secs) do
        local c = built.colors[s.mat]
        comp:CreateMeshSection_LinearColor(i - 1, s.v, s.t, s.n, {}, {}, {}, {}, {}, {}, false)
        if base then
            local mid = comp:CreateDynamicMaterialInstance(i - 1, base, FName("PTSurvivor" .. s.mat))
            if valid(mid) then mid:SetVectorParameterValue(FName("Color"), { R = c[1], G = c[2], B = c[3], A = 1 }) end
        end
    end
    return comp
end

-- Gives (remote = true) or takes away the survivor parts of one character; true when the parts are on it.
function M.set(char, remote)
    if not M.enabled() then return false end
    local key = char:GetFullName()
    local b = bodies[key]
    if b and not valid(b.char) then bodies[key], b = nil, nil end
    if not remote then
        if b then
            for _, c in pairs(b.comps) do if valid(c) then c:DestroyComponent() end end
            bodies[key] = nil
        end
        return false
    end
    if b then
        for _, c in pairs(b.comps) do if not valid(c) then bodies[key], b = nil, nil; break end end
        if b then return true end
    end
    if not valid(char.Mesh) then return false end
    if not built then
        local ok, err = pcall(build)
        if not ok then log("PT|error survivor build %s", tostring(err)); M.enabled = function() return false end; return false end
    end
    local base = baseMaterial()
    b = { char = char, comps = {} }
    local n = 0
    for bone, secs in pairs(built) do
        if bone ~= "colors" then
            local ok, comp = pcall(attach, char, bone, secs, base)
            if ok and comp then b.comps[bone] = comp; n = n + 1 else log("PT|error survivor part %s %s", bone, tostring(comp)) end
        end
    end
    bodies[key] = b
    log("PT|survivor on %s parts=%d", key, n)
    return true
end

-- seated: the legs are hidden (car.lua sitPose hides the thigh bones; our parts hang on bones below them)
function M.sit(char, on)
    local b = bodies[char:GetFullName()]
    if not b then return end
    for bone, c in pairs(b.comps) do
        if SITTING[bone] and valid(c) then c:SetVisibility(not on, false) end
    end
end

-- for the scenario: the part components of a character by bone
function M.parts(char) local b = bodies[char:GetFullName()]; return b and b.comps or {} end

return M
